import React from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { Heart, Star, Clock, ChevronRight } from 'lucide-react';
import { useApp } from '../context/AppContext';
import { FOOD_ITEMS } from '../data/mockData';
import { BtnOrange, C, MacroChip, TagPill, RatingBadge } from '../components/UI';

export default function FoodDetailScreen() {
  const { id } = useParams();
  const navigate = useNavigate();
  const { favorites, toggleFavoriteFood } = useApp();

  const food = FOOD_ITEMS.find(f => f.id === id);
  if (!food) return <div style={{ color: '#fff', padding: 20 }}>Food not found.</div>;

  const isFav = favorites.foods.includes(food.id);

  return (
    <div style={{ minHeight: '100vh', maxWidth: 430, margin: '0 auto', background: '#111', paddingBottom: 100 }}>
      {/* Hero image */}
      <div style={{ position: 'relative', height: 280 }}>
        <img src={food.image} alt={food.name} style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
        <div style={{ position: 'absolute', inset: 0, background: 'linear-gradient(to bottom, rgba(0,0,0,0.3) 0%, transparent 50%, #111 100%)' }} />

        {/* Back */}
        <button
          onClick={() => navigate(-1)}
          style={{
            position: 'absolute', top: 16, left: 16,
            background: 'rgba(0,0,0,0.5)', border: 'none', borderRadius: '50%',
            width: 36, height: 36, color: '#fff', fontSize: 18, cursor: 'pointer',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
          }}
        >←</button>

        {/* Fav */}
        <button
          onClick={() => toggleFavoriteFood(food.id)}
          style={{
            position: 'absolute', top: 16, right: 16,
            background: 'rgba(0,0,0,0.5)', border: 'none', borderRadius: '50%',
            width: 36, height: 36, cursor: 'pointer',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
          }}
        >
          <Heart size={18} fill={isFav ? '#ff4d6d' : 'transparent'} color={isFav ? '#ff4d6d' : '#fff'} />
        </button>

        {/* Image dots */}
        <div style={{ position: 'absolute', bottom: 60, left: '50%', transform: 'translateX(-50%)', display: 'flex', gap: 4 }}>
          {[0,1,2].map(i => (
            <div key={i} style={{ width: i === 0 ? 18 : 6, height: 6, borderRadius: 3, background: i === 0 ? C.orange : 'rgba(255,255,255,0.4)', transition: 'width 0.3s' }} />
          ))}
        </div>
      </div>

      {/* Content */}
      <div style={{ padding: '0 16px' }}>
        {/* Title row */}
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 8 }}>
          <h1 style={{ fontSize: 22, fontWeight: 800, color: '#fff', flex: 1, marginRight: 12 }}>{food.name}</h1>
          <RatingBadge rating={food.rating} reviews={food.reviews} />
        </div>

        {/* Meta */}
        <div style={{ display: 'flex', gap: 8, marginBottom: 12, flexWrap: 'wrap' }}>
          <span style={{ fontSize: 12, color: C.muted }}>🔥 {food.calories} kcal</span>
          <span style={{ color: C.border }}>·</span>
          <TagPill label="High Protein" />
          <TagPill label="Low Carb" />
        </div>

        {/* Description */}
        <p style={{ fontSize: 14, color: '#888', lineHeight: 1.7, marginBottom: 20 }}>{food.description}</p>

        {/* Macros */}
        <div style={{ display: 'flex', gap: 8, marginBottom: 20 }}>
          <MacroChip label="Calories" value={food.calories} unit="kcal" />
          <MacroChip label="Protein"  value={food.protein}  unit="g" />
          <MacroChip label="Carbs"    value={food.carbs}    unit="g" />
          <MacroChip label="Fats"     value={food.fat}      unit="g" />
        </div>

        {/* Ingredients */}
        <div style={{ marginBottom: 20 }}>
          <h3 style={{ fontSize: 15, fontWeight: 700, color: '#fff', marginBottom: 10 }}>Ingredients</h3>
          <p style={{ fontSize: 13, color: '#888', lineHeight: 1.8 }}>{food.ingredients.join(', ')}</p>
        </div>

        {/* Reviews */}
        {food.reviews_list?.length > 0 && (
          <div style={{ marginBottom: 20 }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 12 }}>
              <h3 style={{ fontSize: 15, fontWeight: 700, color: '#fff' }}>Reviews</h3>
              <button style={{ background: 'none', border: 'none', color: C.orange, fontSize: 12, fontWeight: 600, cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 4 }}>
                See all <ChevronRight size={12} />
              </button>
            </div>
            {food.reviews_list.map((r, i) => (
              <div key={i} style={{ background: '#1e1e1e', borderRadius: 12, padding: 14, marginBottom: 10, border: `1px solid ${C.border}` }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 6 }}>
                  <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
                    <div style={{ width: 28, height: 28, borderRadius: '50%', background: C.orange, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 12, fontWeight: 700, color: '#fff' }}>
                      {r.avatar}
                    </div>
                    <span style={{ fontSize: 13, fontWeight: 700, color: '#fff' }}>{r.user}</span>
                  </div>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                    {[1,2,3,4,5].map(s => <Star key={s} size={10} fill={s <= r.rating ? C.orange : 'transparent'} color={C.orange} />)}
                    <span style={{ fontSize: 11, color: '#555', marginLeft: 6 }}>{r.time}</span>
                  </div>
                </div>
                <p style={{ fontSize: 13, color: '#aaa', lineHeight: 1.5 }}>{r.comment}</p>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Bottom CTA */}
      <div style={{
        position: 'fixed', bottom: 0, left: '50%', transform: 'translateX(-50%)',
        width: '100%', maxWidth: 430,
        background: '#111', borderTop: `1px solid ${C.border}`,
        padding: '14px 16px 20px',
        display: 'flex', alignItems: 'center', justifyContent: 'space-between',
      }}>
        <div>
          <div style={{ fontSize: 11, color: '#666' }}>Price</div>
          <div style={{ fontSize: 22, fontWeight: 800, color: '#fff' }}>₹{food.price}</div>
        </div>
        <div style={{ width: 200 }}>
          <BtnOrange>Add to Cart</BtnOrange>
        </div>
      </div>
    </div>
  );
}
